import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public String minWindow(String s, String t) {
        if (t.isEmpty() || s.length() < t.length()) return "";

        // need[c] 表示当前窗口还欠多少个 c，用来判断是否补上了真实需求。
        int[] need = new int[128];
        for (char c : t.toCharArray()) need[c]++;

        int missing = t.length();
        int left = 0;
        int bestStart = 0;
        int bestLength = Integer.MAX_VALUE;

        for (int right = 0; right < s.length(); right++) {
            char incoming = s.charAt(right);

            // 原来还欠这个字符时，吃进它才算补上一个需求。
            if (need[incoming] > 0) missing--;
            need[incoming]--;

            // 已覆盖 t 后尽量右移左边界，才能得到更短的合法窗口。
            while (missing == 0) {
                int length = right - left + 1;
                if (length < bestLength) {
                    bestLength = length;
                    bestStart = left;
                }

                char outgoing = s.charAt(left++);
                need[outgoing]++;

                // 归还后重新变成正数，说明移走的是必需字符，窗口不再合法。
                if (need[outgoing] > 0) missing++;
            }
        }

        return bestLength == Integer.MAX_VALUE
                ? ""
                : s.substring(bestStart, bestStart + bestLength);
    }
}

